lessons.solution:
import java.util.*;
public class Main {
    static String escape(String v){return v.replace("\\","\\\\").replace("\"","\\\"");}
    public static void main(String[] args){Scanner s=new Scanner(System.in);int n=s.nextInt();LinkedHashMap<String,String> fields=new LinkedHashMap<>();for(int i=0;i<n;i++){String key=s.next(),value=s.next();if(fields.containsKey(key)){System.out.println("DUPLICATE_KEY "+key);return;}fields.put(key,value);}StringBuilder sb=new StringBuilder("{");boolean first=true;for(Map.Entry<String,String> e:fields.entrySet()){if(!first)sb.append(",");sb.append("\"").append(e.getKey()).append("\":\"").append(escape(e.getValue())).append("\"");first=false;}System.out.println(sb.append("}"));}
}

