import java.util.*;
public class Main {
    static String escape(String v){return v.replace("\\","\\\\").replace("\"","\\\"");}
    static Integer age(String raw){try{return Integer.valueOf(raw);}catch(NumberFormatException e){return null;}}
    public static void main(String[] args){Scanner s=new Scanner(System.in);int n=s.nextInt();List<String> items=new ArrayList<>();for(int k=1;k<=n;k++){String name=s.next(),raw=s.next(),status=s.next();Integer value=age(raw);String reason=name.equals("null")?"NAME":(value==null||value<0||value>150)?"AGE":(!status.equals("active")&&!status.equals("inactive"))?"STATUS":null;if(reason!=null){System.out.println("INVALID "+k+" "+reason);continue;}items.add("{\"name\":\""+escape(name)+"\",\"age\":"+value+",\"status\":\""+status.toUpperCase(Locale.ROOT)+"\"}");}System.out.println("["+String.join(",",items)+"]");}
}
